/**
 * Represents an LLM provider detected in the environment.
 * Can be from BYOK (API keys) or Subscriptions (OAuth).
 */
interface DetectedProvider {
    id: string;
    type: "byok" | "subscription";
    availableModels: string[];
    capabilities: ("chat" | "embedding" | "rerank" | "decision")[];
}
/**
 * Represents a plugin, skill, MCP, or tool that JYN can manage.
 */
interface CapabilityEntry {
    id: string;
    name: string;
    type: "plugin" | "mcp" | "skill" | "tool";
    scope: "global" | "workspace";
    description: string;
    triggers: string[];
    tokensCost: number;
}
/**
 * The current state of the user's workspace.
 */
interface WorkspaceProfile {
    path: string;
    techStack: string[];
    activePlugins: string[];
    activeMcps: string[];
    activeSkills: string[];
    totalEstimatedTokenCost: number;
}
/**
 * The recommendation generated by JYN's engine.
 */
interface JynRecommendation {
    action: "enable" | "disable" | "install" | "move-scope";
    targetId: string;
    reason: string;
    estimatedTokenSavings?: number;
}

/**
 * Memindai direktori workspace untuk mengumpulkan informasi tech stack
 * dan konfigurasi yang saat ini aktif.
 */
declare function scanWorkspace(workspacePath: string): Promise<WorkspaceProfile>;

declare const MOCK_GLOBAL_PLUGINS: CapabilityEntry[];
declare function scanGlobalConfig(): Promise<CapabilityEntry[]>;

declare function generateRecommendations(profile: WorkspaceProfile, globalPlugins: CapabilityEntry[]): JynRecommendation[];

export { type CapabilityEntry, type DetectedProvider, type JynRecommendation, MOCK_GLOBAL_PLUGINS, type WorkspaceProfile, generateRecommendations, scanGlobalConfig, scanWorkspace };
